{
	return [NSString stringWithFormat:
			@"==> %@ (Mock App): 1.0.0 (auto_updates)\n"
			@"A mock cask used for Cakebrew UI tests.\n"
			@"https://example.com/cask\n"
			@"Installed (on request)\n"
			@"/usr/local/Caskroom/%@/1.0.0 (10MB)\n"
