97	{
98		errorPipe = [NSPipe pipe];
99		[self.task setStandardError:errorPipe];
100	}
101	
102	- (void)configureOutputFileHandle
103	{
104		outputFileHandle = [outputPipe fileHandleForReading];
105		if ([self shouldUsePartialUpdates])
106		{
107			[outputFileHandle waitForDataInBackgroundAndNotify];
108			outputHandlerObserver = [[NSNotificationCenter defaultCenter] addObserverForName:NSFileHandleDataAvailableNotification
109																					  object:outputFileHandle
110																					   queue:[NSOperationQueue currentQueue]
111																				  usingBlock:^(NSNotification *note) {
112																					  [self updatedFileHandle:note];
113																				  }];
114		}
115	}
116	
117	- (void)configureErrorFileHandle
118	{
119		errorFileHandle = [errorPipe fileHandleForReading];
120		if ([self shouldUsePartialUpdates] )
121		{
122			[errorFileHandle waitForDataInBackgroundAndNotify];
123			errorHandlerObserver = [[NSNotificationCenter defaultCenter] addObserverForName:NSFileHandleDataAvailableNotification
124																					 object:errorFileHandle
125																					  queue:[NSOperationQueue currentQueue]
126																				 usingBlock:^(NSNotification *note) {
127																					 [self updatedFileHandle:note];
128																				 }];
129		}
130	}
131	
132	- (void)processStandardOutput
133	{
134		if (![self shouldUsePartialUpdates]) {
135			NSData *data = [outputFileHandle readDataToEndOfFile];
136			if ([data length]) {
137				self.output = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
138			}
139			
140		} else {
141			if ([outputData length]) {
142				self.output = [[NSString alloc] initWithData:outputData encoding:NSUTF8StringEncoding];
143			}
144		}
145	}
146	
147	- (void)processStandardError
148	{
149		if(![self shouldUsePartialUpdates]) {
150			NSData *data = [errorFileHandle readDataToEndOfFile];
151			if ([data length]) {
152				self.error = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
153			}
154		} else {
155			if ([errorData length]) {
156				self.error = [[NSString alloc] initWithData:errorData encoding:NSUTF8StringEncoding];
157			}
158		}
159	}
160	
161	- (int)execute
162	{
163		[self configureStandardOutput];
164		[self configureStandardError];
165		[self configureOutputFileHandle];
166		[self configureErrorFileHandle];
167		[self beginActivity];
168		@try {
169			[self.task launch];
170			[self.task waitUntilExit]; //this makes sure that we stay in the same run loop (thread); needed for notifications
171			
172			return [self.task terminationStatus];
173		}
174		@catch (NSException *exception) {
175			NSLog(@"Exception: %@", exception);
176			[self cleanup];
177			
178			return -1;
179		}
180	}
181	
182	- (void)updatedFileHandle:(NSNotification*)notification
183	{
184		NSFileHandle *fileHandle = [notification object];
185		NSData *data = [fileHandle readDataToEndOfFile];
186	
187		if (fileHandle == outputFileHandle) {
188			[outputData appendData:data];
189		}
190	
191		if (fileHandle == errorFileHandle) {
192			[errorData appendData:data];
193		}
194	
195		[fileHandle waitForDataInBackgroundAndNotify];
196	
197		if (data && data.length > 0) {
198			dispatch_queue_t queue = [self updateBlockQueue];
199	
200			if (queue == nil) {
201				queue = dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_HIGH, 0);
202			}
203	
204			dispatch_async(queue, ^{
205				if (self.updateBlock) {
206					self.updateBlock([[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding]);
207				}
208			});
209		}
210	}
211	
212	- (void)taskDidTerminate:(NSNotification *)notification
213	{
214		[self processStandardOutput];
215		[self processStandardError];
216	
217		[[NSNotificationCenter defaultCenter] removeObserver:self];
218		[[NSNotificationCenter defaultCenter] removeObserver:outputHandlerObserver];
219		[[NSNotificationCenter defaultCenter] removeObserver:errorHandlerObserver];
