169	{
170		NSString *userShell = [[[NSProcessInfo processInfo] environment] objectForKey:@"SHELL"];
171		
172		// avoid executing stuff like /sbin/nologin as a shell
173		BOOL isValidShell = NO;
174		for (NSString *validShell in [[NSString stringWithContentsOfFile:@"/etc/shells" encoding:NSUTF8StringEncoding error:nil] componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]])
175		{
176			if ([[validShell stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]] isEqualToString:userShell])
177			{
178				isValidShell = YES;
179				break;
180			}
181		}
182		
183		if (!isValidShell)
184		{
185			static NSAlert *alert = nil;
186			if (!alert) {
187				alert = [[NSAlert alloc] init];
188				[alert setMessageText:NSLocalizedString(@"Message_Shell_Invalid_Title", nil)];
