lines = [output componentsSeparatedByString:@"\n"];

// `brew info` can return output that doesn't match the expected layout
// (errors, taps, new formats). The parser below indexes specific lines and
// columns, so parse defensively: bail on any out-of-range access rather than
// crash the app (the exception is otherwise thrown on a background queue).
@try {

lineIndex = 0;
line = [lines objectAtIndex:lineIndex];
[self setLatestVersion:[line substringFromIndex:[line rangeOfString:@":"].location+2]];

lineIndex = 1;
line = [lines objectAtIndex:lineIndex];

// Some formulae have a one-line description before the homepage, others jump
// straight to the homepage. Decide by whether the line looks like a web URL.
// (We can't use +[NSURL URLWithString:] returning nil to detect the homepage:
// modern NSURL percent-encodes arbitrary text and returns a non-nil URL, so a
// description like "Play, record, ..." would wrongly be taken as the website.)
if (BPLineLooksLikeWebsite(line))
{
	[self setWebsite:[NSURL URLWithString:line]];
}
else
{
	[self setShortDescription:line];

	lineIndex = 2;
	line = [lines objectAtIndex:lineIndex];
	[self setWebsite:[NSURL URLWithString:line]];
}

lineIndex++;
line = [lines objectAtIndex:lineIndex];
if ([line rangeOfString:@"Conflicts with:"].location != NSNotFound)
{
	if ([line isEqualToString:@"Conflicts with:"])
	{
		// One conflict per line
		NSMutableArray<NSString *> *conflicts = [NSMutableArray new];

		do
		{
			lineIndex++;
			line = [lines objectAtIndex:lineIndex];

			if ([line hasPrefix:@"  "])
			{
				[conflicts addObject:[line stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]]];
			}
		}
		while ([line hasPrefix:@"  "]);

		[self setConflicts:[conflicts componentsJoinedByString:@", "]];
	}
	else
	{
		[self setConflicts:[line substringFromIndex:16]];
		lineIndex++;
		line = [lines objectAtIndex:lineIndex];
	}
}

if (![line isEqualToString:@"Not installed"])
{
	if ([line isEqualToString:@""]) { //keg-only formual has no path
		lineIndex += 1;
		[self setInstallPath:[lines objectAtIndex:lineIndex]];
	} else {
		[self setInstallPath:line];
	}
}

