- (instancetype)init;
@end

@interface BPHomebrewInterfaceListCallAllCasks : BPHomebrewInterfaceListCall
- (instancetype)init;
@end

@interface BPHomebrewInterfaceListCallTests : XCTestCase
@end

@implementation BPHomebrewInterfaceListCallTests

