168	- (NSString *)getValidUserShellPath
169	{
170		NSString *userShell = [[[NSProcessInfo processInfo] environment] objectForKey:@"SHELL"];
171		
172		// avoid executing stuff like /sbin/nologin as a shell
173		BOOL isValidShell = NO;
174		for (NSString *validShell in [[NSString stringWithContentsOfFile:@"/etc/shells" encoding:NSUTF8StringEncoding error:nil] componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]])
175		{
176			if ([[validShell stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]] isEqualToString:userShell])
177			{
178				isValidShell = YES;
179				break;
180			}
181		}
182		
183		if (!isValidShell)
184		{
185			static NSAlert *alert = nil;
186			if (!alert) {
187				alert = [[NSAlert alloc] init];
188				[alert setMessageText:NSLocalizedString(@"Message_Shell_Invalid_Title", nil)];
189				[alert addButtonWithTitle:NSLocalizedString(@"Generic_OK", nil)];
190				[alert setInformativeText:[NSString stringWithFormat:NSLocalizedString(@"Message_Shell_Invalid_Body", nil), userShell]];
191			}
192			// Intentionally app-modal: this runs deep in the interface layer on a
193			// background thread with no window to anchor a sheet, and it blocks a
194			// fatal "no usable shell" path that must halt before returning nil.
195			[alert performSelectorOnMainThread:@selector(runModal) withObject:nil waitUntilDone:YES];
196			
197			NSLog(@"No valid shell found...");
198			return nil;
199		}
200		
201	#ifdef DEBUG
202		NSLog(@"shell: %@", userShell);
203	#endif
204		
205		return userShell;
