74	- (void)reloadFromInterfaceRebuildingCache:(BOOL)shouldRebuildCache;
75	{
76		NSUInteger previousCountOfAllFormulae = [self allFormulae].count;
77	
78		dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_BACKGROUND, 0), ^{
79			[[BPHomebrewInterface sharedInterface] setDelegate:self];
80			
81			NSArray *installedFormulae = [[BPHomebrewInterface sharedInterface] listMode:kBPListInstalled];
82			NSArray *leavesFormulae = [[BPHomebrewInterface sharedInterface] listMode:kBPListLeaves];
83			NSArray *outdatedFormulae = [[BPHomebrewInterface sharedInterface] listMode:kBPListOutdated];
84			NSArray *repositoriesFormulae = [[BPHomebrewInterface sharedInterface] listMode:kBPListRepositories];
85			NSArray *pinnedFormulae = [[BPHomebrewInterface sharedInterface] listMode:kBPListPinned];
86			NSArray *installedCasks = [[BPHomebrewInterface sharedInterface] listMode:kBPListInstalledCasks];
87			NSArray *outdatedCasks = [[BPHomebrewInterface sharedInterface] listMode:kBPListOutdatedCasks];
88			NSArray *services = [[BPHomebrewInterface sharedInterface] listServices];
89			NSArray *allFormulae = nil;
90			NSArray *allCasks = nil;
91	
92			// The full catalogs (`brew formulae` / `brew casks`) are slow, so both
93			// ride the same 24h disk cache and refresh together. The allCasks nil
94			// check refreshes a warm cache written before casks were cached.
95			if (![self loadAllFormulaeCaches] || previousCountOfAllFormulae <= 100 || self.allCasks == nil || shouldRebuildCache) {
96				allFormulae = [[BPHomebrewInterface sharedInterface] listMode:kBPListAll];
97				allCasks = [[BPHomebrewInterface sharedInterface] listMode:kBPListAllCasks];
98			}
99	
100			dispatch_async(dispatch_get_main_queue(), ^{
101	
102				if (allFormulae != nil) {
103					[self setAllFormulae:allFormulae];
104					[self setAllCasks:allCasks];
105					[self storeAllFormulaeCaches];
106				}
107	
108				[self setInstalledFormulae:installedFormulae];
109				[self setLeavesFormulae:leavesFormulae];
110				[self setOutdatedFormulae:outdatedFormulae];
111				[self setRepositoriesFormulae:repositoriesFormulae];
112				[self setPinnedFormulae:pinnedFormulae];
113				[self setInstalledCasks:installedCasks];
114				[self setOutdatedCasks:outdatedCasks];
115				[self setServices:services];
116	
117				[self.delegate homebrewManagerFinishedUpdating:self];
118			});
119		});
