141	/**
142	 Returns `YES` if cache exists, was created less than 24 hours ago and was loaded successfully. Otherwise returns `NO`.
143	 */
144	- (BOOL)loadAllFormulaeCaches
145	{
146		NSURL *cachesFolder = [BPAppDelegate urlForApplicationCachesFolder];
147		NSURL *allFormulaeFile = [cachesFolder URLByAppendingPathComponent:@"allFormulae.cache.bin"];
148		BOOL shouldLoadCache = NO;
149		
150		if ([[NSUserDefaults standardUserDefaults] objectForKey:kBPCacheLastUpdateKey])
151		{
152			NSDate *storageDate = [NSDate dateWithTimeIntervalSince1970:[[NSUserDefaults standardUserDefaults]
153																		 integerForKey:kBPCacheLastUpdateKey]];
154			
155			if ([[NSDate date] timeIntervalSinceDate:storageDate] <= 3600*24)
156			{
157				shouldLoadCache = YES;
158			}
159		}
160		
161		if (shouldLoadCache && allFormulaeFile)
162		{
163			NSDictionary *cacheDict = nil;
164			
165			if ([[NSFileManager defaultManager] fileExistsAtPath:allFormulaeFile.relativePath])
166			{
167				NSData *data = [NSData dataWithContentsOfFile:allFormulaeFile.relativePath];
168				NSError *error = nil;
169	
170				NSSet *classes = [NSSet setWithArray:@[[NSDictionary class], [NSArray class], [NSMutableArray class], [BPFormula class], [NSString class], [NSURL class], [NSNumber class], [BPFormulaOption class]]];
171				cacheDict = [NSKeyedUnarchiver unarchivedObjectOfClasses:classes fromData:data error:&error];
172				if (error) {
173					NSLog(@"Failed decoding data: %@", [error localizedDescription]);
174				}
175				self.allFormulae = [cacheDict objectForKey:kBPCacheDataKey];
176				self.allCasks = [cacheDict objectForKey:kBPCacheCasksDataKey];
177			}
178		}
179		else
180		{
181			// Delete all cache data
182			[[NSFileManager defaultManager] removeItemAtURL:allFormulaeFile error:nil];
183			[[NSUserDefaults standardUserDefaults] removeObjectForKey:kBPCacheLastUpdateKey];
184		}
185		
186		return self.allFormulae != nil;
187	}
