190	{
191		if (self.allFormulae)
192		{
193			NSURL *cachesFolder = [BPAppDelegate urlForApplicationCachesFolder];
194			if (cachesFolder)
195			{
196				NSURL *allFormulaeFile = [cachesFolder URLByAppendingPathComponent:@"allFormulae.cache.bin"];
197				NSDate *storageDate = [NSDate date];
198				
199				if ([[NSUserDefaults standardUserDefaults] objectForKey:kBPCacheLastUpdateKey])
200				{
201					storageDate = [NSDate dateWithTimeIntervalSince1970:[[NSUserDefaults standardUserDefaults]
202																		 integerForKey:kBPCacheLastUpdateKey]];
203				}
204				
205				NSDictionary *cacheDict = @{kBPCacheDataKey: self.allFormulae,
206											kBPCacheCasksDataKey: self.allCasks ?: @[]};
207				NSError *error = nil;
208				NSData *cacheData = [NSKeyedArchiver archivedDataWithRootObject:cacheDict
209															  requiringSecureCoding:YES
210																			  error:&error];
211	
212				if (error || !cacheData) {
213					NSLog(@"Failed encoding data: %@", [error localizedDescription]);
214					return;
215				}
216	
217				if ([[NSFileManager defaultManager] fileExistsAtPath:allFormulaeFile.relativePath])
218				{
219					[cacheData writeToURL:allFormulaeFile atomically:YES];
220				}

